def topo_sort(graph):
    in_degree = {u: 0 for u in graph}
    for u in graph:
        for v in graph[u]:
            if v in in_degree:
                in_degree[v] += 1
            else:
                # Handle cases where a dependency is not a key in the graph dict
                in_degree[v] = 1

    queue = [u for u in in_degree if in_degree[u] == 0]
    result = []

    while queue:
        u = queue.pop(0)
        result.append(u)
        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

    if len(result) != len(in_degree):
        return None
    return result
```

