def normalize(path):
    if not path:
        return "."

    is_absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not is_absolute:
                stack.append('..')
        else:
            stack.append(part)

    result = '/'.join(stack)

    if is_absolute:
        return '/' + result if result else '/'
    else:
        return result if result else '.'
```

