import urllib.parse

def parse_query(qs):
    result = {}
    pairs = qs.split('&')
    for pair in pairs:
        if not pair:
            continue
        try:
            k, v = pair.split('=', 1)
        except ValueError:
            k, v = pair, ""

        key = urllib.parse.unquote_plus(k)
        value = urllib.parse.unquote_plus(v)

        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result
```

