function debounceCount(fn, ms) {
  let timer = null;
  let callCount = 0;

  const debounced = function(...args) {
    callCount++;
    if (timer) clearTimeout(timer);

    timer = setTimeout(() => {
      fn(...args);
      timer = null;
    }, ms);
  };

  const flush = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
      fn();
    }
  };

  return {
    call: debounced,
