function rotateArray(arr, k) {
  const n = arr.length;
  if (n === 0) return [];

  // Normalize k to handle k > n and negative k
  let effectiveK = k % n;
  if (effectiveK < 0) {
    effectiveK += n;
  }

  // If effectiveK is 0, return a copy of the original array
  if (effectiveK === 0) {
    return [...arr];
  }

  const splitIndex = n - effectiveK;
  const rightPart = arr.slice(splitIndex);
  const leftPart = arr.slice(0, splitIndex);

  return [...rightPart, ...leftPart];
}

module.exports = rotateArray;
```

