import React, { useState, useEffect } from 'react';
import {
  StyleSheet,
  Text,
  View,
  FlatList,
  ActivityIndicator,
  SafeAreaView,
} from 'react-native';

const DATA_SIZE = 20;

const InfiniteScrollList = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Mock API call
  const fetchData = async (pageNum) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        const newData = Array.from({ length: DATA_SIZE }, (_, i) => ({
          id: (pageNum - 1) * DATA_SIZE + i,
          title: `Item ${(pageNum - 1) * DATA_SIZE + i + 1}`,
        }));
        resolve(newData);
      }, 1500);
    });
  };

  const loadMoreData = async () => {
    if (loading) return;

    setLoading(true);
    const nextPage = page + 1;
    const newData = await fetchData(nextPage);

    setData((prevData) => [...prevData, ...newData]);
    setPage(nextPage);
    setLoading(false);
  };

  const refreshList = async () => {
    setIsRefreshing(true);
    const newData = await fetchData(1);
    setData(newData);
    setPage(1);
    setIsRefreshing(false);
  };

  useEffect(() => {
    const initData = async () => {
      const initialData = await fetchData(1);
      setData(initialData);
      setPage(2);
    };
    initData();
  }, []);

  const renderItem = ({ item }) => (
    <View style={styles.item}>
      <Text style={styles.title}>{item.title}</Text>
    </View>
  );

  const renderFooter = () => {
    if (!loading) return null;
    return (
      <View style={styles.loaderContainer}>
        <ActivityIndicator size="large" color="#0000ff" />
      </View>
    );
  };

